#pragma once

#include <cstddef>
#include <cstdint>

// Tables for unicode_cpts_normalize_nfkc() (UAX #15), generated by scripts/gen-unicode-nfkc-data.py.

struct unicode_nfkd_entry {
    uint32_t cpt;
    uint32_t offset;  // into unicode_nfkd_data
    uint32_t length;
};

struct unicode_ccc_range {
    uint32_t first;
    uint32_t last;
    uint8_t  ccc;
};

struct unicode_compose_entry {
    uint32_t first;
    uint32_t second;
    uint32_t composite;
};

extern const unicode_nfkd_entry    unicode_nfkd_map[];       // sorted by cpt; Hangul syllables are not listed
extern const size_t                unicode_nfkd_map_size;
extern const uint32_t              unicode_nfkd_data[];
extern const unicode_ccc_range     unicode_ccc_ranges[];     // sorted, ccc != 0 only
extern const size_t                unicode_ccc_ranges_size;
extern const unicode_compose_entry unicode_compose_pairs[];  // sorted by (first, second); Hangul composes algorithmically
extern const size_t                unicode_compose_pairs_size;
